	consent_file_id INTEGER, 
	is_featured BOOLEAN NOT NULL, 
	is_new BOOLEAN NOT NULL, 
	"order" INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
