    name VARCHAR(150) NOT NULL,
    phone VARCHAR(20) NOT NULL,
    comment VARCHAR(500) NOT NULL DEFAULT '',
    is_handled BOOLEAN NOT NULL DEFAULT 0,
    ip VARCHAR(64) NOT NULL DEFAULT '',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);CREATE TABLE courses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title_uz VARCHAR(200) NOT NULL DEFAULT '',
    title_ru VARCHAR(200) NOT NULL DEFAULT '',
    title_en VARCHAR(200) NOT NULL DEFAULT '',
    description_uz TEXT NOT NULL DEFAULT '',
    description_ru TEXT NOT NULL DEFAULT '',
    description_en TEXT NOT NULL DEFAULT '',
    image_id INTEGER REFERENCES media(id) ON DELETE SET NULL,
    duration VARCHAR(100) NOT NULL DEFAULT '',
    price INTEGER,
    price_text VARCHAR(100) NOT NULL DEFAULT '',
    "order" INTEGER NOT NULL DEFAULT 0,
    is_active BOOLEAN NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);INSERT INTO "courses" VALUES(1,'Pre-IELTS va General English','Pre-IELTS и General English','Pre-IELTS & General English','Ingliz tili grammatikasi, so''z boyligi va erkin muloqot ko''nikmalarini oshirish. Barcha yoshdagi o''quvchilar uchun bosqichma-bosqich o''qitish dasturi.','Развитие грамматики, словарного запаса и разговорной речи. Поэтапная программа для всех уровней.','English grammar, vocabulary, and fluent speaking skills. Step-by-step program for students of all ages.',NULL,'3 oy',600000,'Oyiga 600 000 so''m',0,1,'2026-11-11 03:06:39','2026-11-11 03:06:39');INSERT INTO "courses" VALUES(2,'IELTS Intensive (7.0+ Kafolati)','IELTS Intensive (Гарантия 7.0+)','IELTS Intensive (7.0+ Guarantee)','Listening, Reading, Writing va Speaking bo''yicha chuqurlashtirilgan tayyorgarlik. Mock imtihonlar va xalqaro sertifikatga ega ustozlar ko''magi.','Интенсивная подготовка по всем секциям IELTS: Listening, Reading, Writing, Speaking. Пробные экзамены и опытные педагоги.','Comprehensive preparation across all IELTS sections with mock tests and expert certified mentors.',NULL,'4 oy',800000,'Oyiga 800 000 so''m',1,1,'2026-11-11 03:06:39','2026-11-11 03:06:39');INSERT INTO "courses" VALUES(3,'Pre-School — Maktabga tayyorlov','Pre-School — Подготовка к школе','Pre-School — School Readiness','5-6 yoshli bolalar uchun: savodxonlik, mantiqiy fikrlash, matematika va chet tili asoslari. Maktab muhitiga qulay moslashish.','Для детей 5–6 лет: грамота, логическое мышление, арифметика и основы иностранного языка. Плавная адаптация к школе.','For 5–6 year-olds: literacy, logical reasoning, mathematics, and early language foundations.',NULL,'6 oy',500000,'Oyiga 500 000 so''m',2,1,'2026-11-11 03:06:39','2026-11-11 03:06:39');INSERT INTO "courses" VALUES(4,'Mental Arifmetika va Mantiq','Ментальная арифметика и логика','Mental Arithmetic & Logic','Miyaning o''ng va chap yarim sharlarini rivojlantirish, tezkor hisoblash hamda xotirani kuchaytirish mashg''ulotlari.','Развитие обоих полушарий мозга, быстрый счёт в уме и укрепление памяти для детей школьного возраста.','Fast mental calculations, photographic memory training, and balanced cognitive development.',NULL,'3 oy',550000,'Oyiga 550 000 so''m',3,1,'2026-11-11 03:06:39','2026-11-11 03:06:39');INSERT INTO "courses" VALUES(5,'Olimpiada Matematikasi','Олимпиадная математика','Olympiad Mathematics','Murakkab masalalar yechish metodikasi, noan''anaviy yondashuv va tuman/viloyat/respublika fan olimpiadalariga maxsus tayyorgarlik.','Методы решения нестандартных задач, развитие гибкого мышления и подготовка к олимпиадам всех уровней.','Advanced problem solving, analytical thinking, and preparation for local and national competitions.',NULL,'6 oy',700000,'Oyiga 700 000 so''m',4,1,'2026-11-11 03:06:39','2026-11-11 03:06:39');INSERT INTO "courses" VALUES(6,'Robototexnika va IT Kids','Робототехника и IT Kids','Robotics & IT Kids','Dasturlash asoslari (Scratch, Python), elektronika va robotlar yasash orqali zamonaviy texnologik tafakkurni shakllantirish.','Основы программирования на Scratch и Python, конструирование роботов и развитие инженерного мышления.','Foundations of coding in Scratch and Python, electronics, and hands-on robotics engineering.',NULL,'4 oy',650000,'Oyiga 650 000 so''m',5,1,'2026-11-11 03:06:39','2026-11-11 03:06:39');CREATE TABLE faqs (
	id INTEGER NOT NULL, 
	question_uz VARCHAR(500) NOT NULL, 
	question_ru VARCHAR(500) NOT NULL, 
	question_en VARCHAR(500) NOT NULL, 
	answer_uz TEXT NOT NULL, 
	answer_ru TEXT NOT NULL, 
	answer_en TEXT NOT NULL, 
	"order" INTEGER NOT NULL, 
	is_visible BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);INSERT INTO "faqs" VALUES(1,'O''quv yili o''rtasida qabul qilasizlarmi?','Принимаете ли вы в середине учебного года?','Do you accept students mid-year?','Ha, bo''sh joy bo''lsa, istalgan vaqtda.','Да, при наличии свободных мест — в любое время.','Yes, at any time if there are free places.',0,1,'2026-11-07 10:05:27.652069');INSERT INTO "faqs" VALUES(2,'Ovqat narxga kiradimi?','Входит ли питание в стоимость?','Are meals included in the price?','3 mahal issiq ovqat alohida to''lanadi: oyiga 900 000 so''m.','3-разовое горячее питание оплачивается отдельно: 900 000 сумов в месяц.','Three hot meals a day are paid separately: 900,000 UZS per month.',1,1,'2026-11-07 10:05:27.652072');INSERT INTO "faqs" VALUES(3,'Transport bormi?','Есть ли школьный транспорт?','Is there school transport?','Ha, Chilonzor, Yakkasaroy, Sergeli va Uchtepa tumanlaridan. Oyiga 500 000 so''m.','Да, из Чиланзарского, Яккасарайского, Сергелийского и Учтепинского районов. 500 000 сумов в месяц.','Yes, from the Chilanzar, Yakkasaray, Sergeli and Uchtepa districts. 500,000 UZS per month.',2,1,'2026-11-07 10:05:27.652073');INSERT INTO "faqs" VALUES(4,'Aka-ukalar uchun chegirma bormi?','Есть ли скидка для братьев и сестёр?','Is there a sibling discount?','Ikkinchi farzand uchun 10%, uchinchi farzand uchun 15% chegirma.','Скидка 10% на второго ребёнка и 15% на третьего.','10% off for the second child and 15% for the third.',3,1,'2026-11-07 10:05:27.652073');INSERT INTO "faqs" VALUES(5,'Darslar soat nechada tugaydi?','Во сколько заканчиваются уроки?','What time do lessons end?','Asosiy darslar 12:30 gacha, to''liq kun guruhi 18:00 gacha.','Основные уроки — до 12:30, группа полного дня — до 18:00.','Core lessons end at 12:30; the full-day group stays until 18:00.',4,1,'2026-11-07 10:05:27.652073');CREATE TABLE media (
	id INTEGER NOT NULL, 
	"key" VARCHAR(40) NOT NULL, 
	url VARCHAR(300) NOT NULL, 
	mime VARCHAR(100) NOT NULL, 
	size INTEGER NOT NULL, 
	width INTEGER, 
	height INTEGER, 
	is_private BOOLEAN NOT NULL, 
	files JSON NOT NULL, 
	original_name VARCHAR(255) NOT NULL, 
	album_id INTEGER, 
	alt_uz VARCHAR(300) NOT NULL, 
	alt_ru VARCHAR(300) NOT NULL, 
	alt_en VARCHAR(300) NOT NULL, 
	"order" INTEGER NOT NULL, 
	uploaded_by INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(album_id) REFERENCES albums (id) ON DELETE SET NULL, 
	FOREIGN KEY(uploaded_by) REFERENCES users (id) ON DELETE SET NULL
);INSERT INTO "media" VALUES(1,'d6307371e8c43429','/media/public/d6307371e8c43429.webp','image/jpeg',544242,1672,941,0,'{"original": "private/originals/d6307371e8c43429.jpg", "full": "public/d6307371e8c43429.webp", "thumb": "public/d6307371e8c43429_thumb.webp", "medium": "public/d6307371e8c43429_medium.webp", "large": "public/d6307371e8c43429_large.webp"}','school_entrance.jpg',1,'Smart Start maktab binosi','Здание школы Smart Start','Smart Start school building',1,1,'2026-11-07 10:05:23.912141');INSERT INTO "media" VALUES(2,'b189d64cec3165f8','/media/public/b189d64cec3165f8.webp','image/jpeg',653220,1672,941,0,'{"original": "private/originals/b189d64cec3165f8.jpg", "full": "public/b189d64cec3165f8.webp", "thumb": "public/b189d64cec3165f8_thumb.webp", "medium": "public/b189d64cec3165f8_medium.webp", "large": "public/b189d64cec3165f8_large.webp"}','school_entrance_family.jpg',1,'Ota-onalar va bolalar maktab kirishida','Родители и дети у входа в школу','Families arriving at the school entrance',2,1,'2026-11-07 10:05:24.547760');INSERT INTO "media" VALUES(3,'4c43a2e3ff3273e5','/media/public/4c43a2e3ff3273e5.webp','image/jpeg',881415,1200,896,0,'{"original": "private/originals/4c43a2e3ff3273e5.jpg", "full": "public/4c43a2e3ff3273e5.webp", "thumb": "public/4c43a2e3ff3273e5_thumb.webp", "medium": "public/4c43a2e3ff3273e5_medium.webp", "large": "public/4c43a2e3ff3273e5_large.webp"}','classroom.jpg',2,'Smart Start sinfxonasida dars','Урок в классе Smart Start','A lesson in a Smart Start classroom',1,1,'2026-11-07 10:05:24.944567');INSERT INTO "media" VALUES(4,'70b94eb752c4b36a','/media/public/70b94eb752c4b36a.webp','image/jpeg',916854,1376,768,0,'{"original": "private/originals/70b94eb752c4b36a.jpg", "full": "public/70b94eb752c4b36a.webp", "thumb": "public/70b94eb752c4b36a_thumb.webp", "medium": "public/70b94eb752c4b36a_medium.webp", "large": "public/70b94eb752c4b36a_large.webp"}','stage_primary.jpg',2,'Boshlang''ich sinf o''quvchilari','Ученики начальной школы','Primary sc