TABLE notification_log (
	id INTEGER NOT NULL, 
	channel VARCHAR(20) NOT NULL, 
	event VARCHAR(50) NOT NULL, 
	ok BOOLEAN NOT NULL, 
	error VARCHAR(500) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);CREATE TABLE pages (
	id INTEGER NOT NULL, 
	"key" VARCHAR(50) NOT NULL, 
	blocks_uz JSON NOT NULL, 
	blocks_ru JSON NOT NULL, 
	blocks_en JSON NOT NULL, 
	seo_title_uz VARCHAR(300) NOT NULL, 
	seo_title_ru VARCHAR(300) NOT NULL, 
	seo_title_en VARCHAR(300) NOT NULL, 
	seo_description_uz VARCHAR(500) NOT NULL, 
	seo_description_ru VARCHAR(500) NOT NULL, 
	seo_description_en VARCHAR(500) NOT NULL, 
	og_image_id INTEGER, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(og_image_id) REFERENCES media (id) ON DELETE SET NULL
);INSERT INTO "pages" VALUES(1,'home','{"logo": 7, "hero": {"badge": "Smart Start Xususiy Maktabi \u00b7 2022-yildan beri", "admission_open": "2026\u20132027 o''quv yiliga qabul ochiq", "title": "Farzandingizning kelajagi bugun boshlanadi", "title_accent": "bugun", "text": "Smart Start \u2014 zamonaviy ta''lim, kuchli ingliz tili va har bir bolaga e''tibor beriladigan xususiy maktab. Kichik sinflar, tajribali o''qituvchilar va xavfsiz muhit.", "motto": "\u00abIlm axloq bilan olinsagina foyda beradi\u00bb", "cta_primary": "Qabulga yozilish", "cta_secondary": "Maktabga ekskursiya", "questions": "Savollar uchun:", "photo_caption": "Smart Start maktab binosi", "image": 1}, "stats": [{"value": 300, "suffix": "+", "label": "o''quvchi"}, {"value": 45, "suffix": "+", "label": "tajribali o''qituvchi"}, {"value": 18, "suffix": "", "label": "sinfda ko''pi bilan o''quvchi"}, {"value": 2022, "suffix": "", "label": "yildan beri ta''lim beramiz"}], "why": [{"icon": "users", "title": "Kichik sinflar", "text": "Sinfda ko''pi bilan 16-18 nafar o''quvchi \u2014 o''qituvchi har bir bolani taniydi va uning sur''atiga moslashadi."}, {"icon": "languages", "title": "Kuchli ingliz tili", "text": "Haftasiga 8-10 soat ingliz tili, IELTS va xalqaro imtihonlarga chuqurlashtirilgan tayyorgarlik."}, {"icon": "clock", "title": "To''liq kun", "text": "Darslar, uy vazifasini o''qituvchi nazoratida bajarish, to''garaklar va issiq 3 mahal ovqat."}, {"icon": "message-circle", "title": "O''qituvchi bilan yaqin aloqa", "text": "Sinf rahbari farzandingizning yutuqlari va qiyinchiliklari haqida muntazam gaplashadi, ota-onalar majlislari har chorakda."}, {"icon": "shield-check", "title": "Xavfsiz muhit", "text": "Videokuzatuv, 24/7 qo''riqlash xizmati, maktab shifokori va qulay xavfsiz transport xizmati."}, {"icon": "award", "title": "Xalqaro sertifikatlar", "text": "IELTS, CEFR, SAT va fan olimpiadalari natijalari \u2014 har bir o''quvchining haqiqiy sertifikati bilan."}], "cta": {"title": "2027\u20132028 o''quv yiliga qabul ochiq", "text": "Joylar soni cheklangan \u2014 arizangizni hoziroq qoldiring, menejerimiz 1 ish kuni ichida qo''ng''iroq qiladi.", "button": "Ariza qoldirish"}, "stages": [{"key": "primary", "badge": "Boshlang''ich sinflar (1\u20134)", "title": "Poydevor va erta rivojlanish", "ages": "7\u201310 yosh", "grades": "1\u20134-sinflar", "text": "Savodxonlik, tez va to''g''ri o''qish, mental arifmetika, ingliz tiliga erta qiziqish va ijodiy fikrlash to''garaklari.", "points": ["Savodxonlik va tez o''qish", "Mental arifmetika va mantiq", "Ingliz tili (Oxford dasturi)", "Kichik guruhlar (16\u201318 nafar)"], "image": 4}, {"key": "middle", "badge": "O''rta maktab (5\u20139)", "title": "Fundamental fanlar va CEFR", "ages": "11\u201315 yosh", "grades": "5\u20139-sinflar", "text": "Chuqurlashtirilgan matematika, fizika, ingliz tilidan milliy va xalqaro CEFR B2/C1 imtihonlariga tizimli tayyorgarlik.", "points": ["Chuqurlashtirilgan matematika va fizika", "CEFR B2/C1 tizimli tayyorgarlik", "Robototexnika va IT laboratoriya", "Fan olimpiadalari guruhi"], "image": 5}, {"key": "high", "badge": "Yuqori maktab (10\u201311)", "title": "IELTS, SAT va OTMga qabul", "ages": "16\u201318 yosh", "grades": "10\u201311-sinflar", "text": "IELTS 7.5+, SAT 1400+, xorijiy va mahalliy nufuzli oliygohlarga grant yutish maqsadida shaxsiy portfolio yaratish.", "points": ["IELTS 7.5+ va SAT 1400+ intensiv", "Top-1000 universitetlarga grantlar", "Xalqaro portfolio va tavsiyanoma", "Shaxsiy mentorlik va OTM yo''llanmasi"], "image": 6}], "day": [{"time": "08:00", "title": "Kutib olish va nonushta", "text": "O''qituvchilar bolalarni eshik oldida iliq kutib oladi va energiya beruvchi nonushta."}, {"time": "08:30", "title": "Asosiy darslar", "text": "Kichik sinflarda, 45 daqiqalik qiziqarli va interaktiv ta''lim darslari."}, {"time": "12:30", "title": "Tushlik va dam olish", "text": "Issiq 3 mahal muvozanatli ovqat va ochiq havoda xavfsiz o''yin/sayr."}, {"time": "14:00", "title": "Ingliz tili", "text": "Qo''shimcha soatlar, so''zlashuvga (Speaking club) asosiy amaliy urg''u."}, {"time": "15:30", "title": "Uy vazifasi", "text": "O''qituvchi nazoratida, maktabning o''zida to''liq va mustaqil bajariladi."}, {"time": "16:30", "title": "To''garaklar", "text": "Robototexnika, shaxmat, sport, tasviriy san''at va mental arifmetika."}], "sections": {"why_title": "Nega Smart Start?", "why_subtitle": "Biz bolalarga yod olishni emas, fikrlashni o''rgatamiz \u2014 va bu jarayonda siz har kuni xabardor bo''lasiz.", "stages_title": "Ta''lim bosqichlari", "stages_text": "Har bir yosh davrining psixologik va intellektual xususiyatlariga moslashtirilgan o''quv dasturi.", "teachers_title": "Farzandingizni kimlar o''qitadi", "teachers_text": "Xalqaro sertifikatlarga ega, ko''p yillik tajribali metodist va o''qituvchilar jamoasi.", "testimonials_title": "Ota-onalar nima deydi", "testimonials_text": "Maktabimizda tahsil olayotgan o''quvchilarning ota-onalari samimiy fikrlari.", "day_badge": "Bir kun Smart Start''da", "day_title": "Ertalabdan kechgacha \u2014 farzandingiz ishonchli qo''llarda", "day_text": "To''liq kun rejimi: darslar, ovqat, dam olish, uy vazifasi va to''garaklar bitta binoda. Ishdan keyin farzandingizni vazifasi to''liq bajarilgan holda olib ketasiz.", "news_title": "Maktab hayoti", "results_kicker": "Ota-onalar uchun", "results_title": "O''quvchilarimiz natijalari", "results_text": "Har bir sertifikat \u2014 haqiqiy o''quvchi va haqiqiy mehnat. Natijalarni tekshirib ko''rishingiz mumkin."}}','{"hero": {"badge": "\u0427\u0430\u0441\u0442\u043d\u0430\u044f \u0448\u043a\u043e\u043b\u0430 Smart Start \u00b7 \u0421 2022 \u0433\u043e\u0434\u0430", "admission_open": "\u041e\u0442\u043a\u0440\u044b\u0442 \u043f\u0440\u0438\u0451\u043c \u043d\u0430 2026\u20132027 \u0443\u0447\u0435\u0431\u043d\u044b\u0439 \u0433\u043e\u0434", "title": "\u0411\u0443\u0434\u0443\u0449\u0435\u0435 \u0432\u0430\u0448\u0435\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441\u0435\u0433\u043e\u0434\u043d\u044f", "title_accent": "\u0441\u0435\u0433\u043e\u0434\u043d\u044f", "text": "Smart Start \u2014 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u0435 \u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u0435, \u0443\u0433\u043b\u0443\u0431\u043b\u0451\u043d\u043d\u044b\u0439 \u0430\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u0438\u0439 \u044f\u0437\u044b\u043a \u0438 \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u043e\u0435 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043a \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0443\u0447\u0435\u043d\u0438\u043a\u0443. \u041d\u0435\u0431\u043e\u043b\u044c\u0448\u0438\u0435 \u043a\u043b\u0430\u0441\u0441\u044b, \u043e\u043f\u044b\u0442\u043d\u044b\u0435 \u043f\u0435\u0434\u0430\u0433\u043e\u0433\u0438 \u0438 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u0430\u044f \u0441\u0440\u0435\u0434\u0430.", "motto": "\u00ab\u0417\u043d\u0430\u043d\u0438\u044f \u043f\u0440\u0438\u043d\u043e\u0441\u044f\u0442 \u0438\u0441\u0442\u0438\u043d\u043d\u0443\u044e \u043f\u043e\u043b\u044c\u0437\u0443 \u043b\u0438\u0448\u044c \u0432 \u0441\u043e\u0447\u0435\u0442\u0430\u043d\u0438\u0438 \u0441 \u0431\u043b\u0430\u0433\u043e\u043d\u0440\u0430\u0432\u0438\u0435\u043c\u00bb", "cta_primary": "\u0417\u0430\u043f\u0438\u0441\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u043f\u0440\u0438\u0451\u043c", "cta_secondary": "\u042d\u043a\u0441\u043a\u0443\u0440\u0441\u0438\u044f \u043f\u043e \u0448\u043a\u043e\u043b\u0435", "questions": "\u041f\u043e \u0432\u0441\u0435\u043c \u0432\u043e\u043f\u0440\u043e\u0441\u0430\u043c:", "photo_caption": "\u0417\u0434\u0430\u043d\u0438\u0435 \u0448\u043a\u043e\u043b\u044b Smart Start"}, "stats": [{"label": "\u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432"}, {"label": "\u043e\u043f\u044b\u0442\u043d\u044b\u0445 \u043f\u0435\u0434\u0430\u0433\u043e\u0433\u043e\u0432"}, {"label": "\u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432 \u0432 \u043a\u043b\u0430\u0441\u0441\u0435"}, {"label": "\u0433\u043e\u0434\u0430 \u043e\u0431\u0443\u0447\u0430\u0435\u043c \u0431\u0443\u0434\u0443\u0449\u0438\u0445 \u043b\u0438\u0434\u0435\u0440\u043e\u0432"}], "why": [{"title": "\u041d\u0435\u0431\u043e\u043b\u044c\u0448\u0438\u0435 \u043a\u043b\u0430\u0441\u0441\u044b", "text": "\u0412 \u043a\u043b\u0430\u0441\u0441\u0435 \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c 16-18 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432 \u2014 \u0443\u0447\u0438\u0442\u0435\u043b\u044c \u0443\u0434\u0435\u043b\u044f\u0435\u0442 \u0432\u043d\u0438\u043c\u0430\u043d\u0438\u0435 \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0438 \u0430\u0434\u0430\u043f\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a \u0435\u0433\u043e \u0442\u0435\u043c\u043f\u0443."}, {"title": "\u0423\u0433\u043b\u0443\u0431\u043b\u0451\u043d\u043d\u044b\u0439 \u0430\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u0438\u0439", "text": "8-10 \u0447\u0430\u0441\u043e\u0432 \u0430\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u043e\u0433\u043e \u0432 \u043d\u0435\u0434\u0435\u043b\u044e, \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u0430\u044f \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u043a IELTS \u0438 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u043c \u044d\u043a\u0437\u0430\u043c\u0435\u043d\u0430\u043c."}, {"title": "\u041f\u043e\u043b\u043d\u044b\u0439 \u0434\u0435\u043d\u044c \u043f\u0440\u0435\u0431\u044b\u0432\u0430\u043d\u0438\u044f", "text": "\u0423\u0440\u043e\u043a\u0438, \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0434\u043e\u043c\u0430\u0448\u043d\u0438\u0445 \u0437\u0430\u0434\u0430\u043d\u0438\u0439 \u043f\u043e\u0434 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0441\u0442\u0432\u043e\u043c \u043f\u0435\u0434\u0430\u0433\u043e\u0433\u043e\u0432, \u0441\u0435\u043a\u0446\u0438\u0438 \u0438 3-\u0440\u0430\u0437\u043e\u0432\u043e\u0435 \u0433\u043e\u0440\u044f\u0447\u0435\u0435 \u043f\u0438\u0442\u0430\u043d\u0438\u0435."}, {"title": "\u0422\u0435\u0441\u043d\u0430\u044f \u0441\u0432\u044f\u0437\u044c \u0441 \u0443\u0447\u0438\u0442\u0435\u043b\u0435\u043c", "text": "\u041a\u043b\u0430\u0441\u0441\u043d\u044b\u0439 \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u043e \u0438\u043d\u0444\u043e\u0440\u043c\u0438\u0440\u0443\u0435\u0442 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043e\u0431 \u0443\u0441\u043f\u0435\u0445\u0430\u0445 \u0438 \u0442\u0440\u0443\u0434\u043d\u043e\u0441\u0442\u044f\u0445 \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0435 \u0441\u043e\u0431\u0440\u0430\u043d\u0438\u044f \u2014 \u043a\u0430\u0436\u0434\u0443\u044e \u0447\u0435\u0442\u0432\u0435\u0440\u0442\u044c."}, {"title": "\u0411\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u0430\u044f \u0441\u0440\u0435\u0434\u0430", "text": "\u0412\u0438\u0434\u0435\u043e\u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u0435, \u043a\u0440\u0443\u0433\u043b\u043e\u0441\u0443\u0442\u043e\u0447\u043d\u0430\u044f \u043e\u0445\u0440\u0430\u043d\u0430 24/7, \u0448\u0442\u0430\u0442\u043d\u044b\u0439 \u0432\u0440\u0430\u0447 \u0438 \u043a\u043e\u043c\u0444\u043e\u0440\u0442\u0430\u0431\u0435\u043b\u044c\u043d\u044b\u0439 \u0448\u043a\u043e\u043b\u044c\u043d\u044b\u0439 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442."}, {"title": "\u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u044b", "text": "\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b IELTS, CEFR, SAT \u0438 \u043e\u043b\u0438\u043c\u043f\u0438\u0430\u0434 \u2014 \u0441 \u043f\u043e\u0434\u043b\u0438\u043d\u043d\u044b\u043c\u0438 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u0430\u043c\u0438 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432."}], "cta": {"title": "\u041e\u0442\u043a\u0440\u044b\u0442 \u043f\u0440\u0438\u0451\u043c \u043d\u0430 2027\u20132028 \u0443\u0447\u0435\u0431\u043d\u044b\u0439 \u0433\u043e\u0434", "text": "\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043c\u0435\u0441\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043e \u2014 \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0437\u0430\u044f\u0432\u043a\u0443 \u043f\u0440\u044f\u043c\u043e \u0441\u0435\u0439\u0447\u0430\u0441, \u043d\u0430\u0448 \u043c\u0435\u043d\u0435\u0434\u0436\u0435\u0440 \u043f\u0435\u0440\u0435\u0437\u0432\u043e\u043d\u0438\u0442 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 1 \u0440\u0430\u0431\u043e\u0447\u0435\u0433\u043e \u0434\u043d\u044f.", "button": "\u041e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0437\u0430\u044f\u0432\u043a\u0443"}, "stages": [{"badge": "\u041d\u0430\u0447\u0430\u043b\u044c\u043d\u0430\u044f \u0448\u043a\u043e\u043b\u0430 (1\u20134)", "title": "\u0424\u0443\u043d\u0434\u0430\u043c\u0435\u043d\u0442 \u0438 \u0440\u0430\u043d\u043d\u0435\u0435 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435", "ages": "7\u201310 \u043b\u0435\u0442", "grades": "1\u20134 \u043a\u043b\u0430\u0441\u0441\u044b", "text": "\u0413\u0440\u0430\u043c\u043e\u0442\u043d\u043e\u0441\u0442\u044c, \u0431\u044b\u0441\u0442\u0440\u043e\u0447\u0442\u0435\u043d\u0438\u0435, \u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430, \u0440\u0430\u043d\u043d\u0435\u0435 \u043f\u043e\u0433\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u0432 \u0430\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u0438\u0439 \u0438 \u0442\u0432\u043e\u0440\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u0440\u0443\u0436\u043a\u0438.", "points": ["\u0413\u0440\u0430\u043c\u043e\u0442\u043d\u043e\u0441\u0442\u044c \u0438 \u0431\u044b\u0441\u0442\u0440\u043e\u0447\u0442\u0435\u043d\u0438\u0435", "\u041c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430", "\u0410\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u0438\u0439 \u043f\u043e \u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0435 Oxford", "\u041c\u0438\u043d\u0438-\u043a\u043b\u0430\u0441\u0441\u044b \u0434\u043e 18 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432"]}, {"badge": "\u0421\u0440\u0435\u0434\u043d\u044f\u044f \u0448\u043a\u043e\u043b\u0430 (5\u20139)", "title": "\u0424\u0443\u043d\u0434\u0430\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043d\u0430\u0443\u043a\u0438 \u0438 CEFR", "ages": "11\u201315 \u043b\u0435\u0442", "grades": "5\u20139 \u043a\u043b\u0430\u0441\u0441\u044b", "text": "\u0423\u0433\u043b\u0443\u0431\u043b\u0451\u043d\u043d\u0430\u044f \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u043a\u0430, \u0444\u0438\u0437\u0438\u043a\u0430, \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u0430\u044f \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u043a \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u043c \u0438 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u043c \u044d\u043a\u0437\u0430\u043c\u0435\u043d\u0430\u043c CEFR B2/C1.", "points": ["\u0423\u0433\u043b\u0443\u0431\u043b\u0451\u043d\u043d\u0430\u044f \u043c\u0430\u0442\u0435\u043c\u0430\u0442\u0438\u043a\u0430 \u0438 \u0444\u0438\u0437\u0438\u043a\u0430", "\u041f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u043a CEFR B2/C1", "STEM, IT \u0438 \u0440\u043e\u0431\u043e\u0442\u043e\u0442\u0435\u0445\u043d\u0438\u043a\u0430", "\u041e\u043b\u0438\u043c\u043f\u0438\u0430\u0434\u043d\u044b\u0435 \u0444\u0430\u043a\u0443\u043b\u044c\u0442\u0430\u0442\u0438\u0432\u044b"]}, {"badge": "\u0421\u0442\u0430\u0440\u0448\u0430\u044f \u0448\u043a\u043e\u043b\u0430 (10\u201311)", "title": "IELTS, SAT \u0438 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0435 \u0432 \u0432\u0443\u0437\u044b", "ages": "16\u201318 \u043b\u0435\u0442", "grades": "10\u201311 \u043a\u043b\u0430\u0441\u0441\u044b", "text": "IELTS 7.5+, SAT 1400+, \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e \u0434\u043b\u044f \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u044f \u043d\u0430 \u0433\u0440\u0430\u043d\u0442\u044b \u0432 \u0432\u0435\u0434\u0443\u0449\u0438\u0435 \u0432\u0443\u0437\u044b.", "points": ["\u0418\u043d\u0442\u0435\u043d\u0441\u0438\u0432 IELTS 7.5+ \u0438 SAT 1400+", "\u0413\u0440\u0430\u043d\u0442\u044b \u0432 \u0422\u041e\u041f-1000 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0438\u0442\u0435\u0442\u043e\u0432", "\u041c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0435 \u043f\u043e\u0440\u0442\u0444\u043e\u043b\u0438\u043e", "\u041f\u0440\u043e\u0444\u043e\u0440\u0438\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u0438 \u043c\u0435\u043d\u0442\u043e\u0440\u0441\u0442\u0432\u043e"]}], "day": [{"title": "\u0412\u0441\u0442\u0440\u0435\u0447\u0430 \u0438 \u0437\u0430\u0432\u0442\u0440\u0430\u043a", "text": "\u0422\u0451\u043f\u043b\u044b\u0439 \u043f\u0440\u0438\u0451\u043c \u0443\u0447\u0438\u0442\u0435\u043b\u044f\u043c\u0438 \u0443 \u0434\u0432\u0435\u0440\u0435\u0439 \u0448\u043a\u043e\u043b\u044b \u0438 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u0439 \u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0437\u0430\u0432\u0442\u0440\u0430\u043a."}, {"title": "\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0443\u0440\u043e\u043a\u0438", "text": "\u0418\u043d\u0442\u0435\u0440\u0430\u043a\u0442\u0438\u0432\u043d\u044b\u0435 \u0438 \u0443\u0432\u043b\u0435\u043a\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 45-\u043c\u0438\u043d\u0443\u0442\u043d\u044b\u0435 \u0443\u0440\u043e\u043a\u0438 \u0432 \u043c\u0438\u043d\u0438-\u0433\u0440\u0443\u043f\u043f\u0430\u0445."}, {"title": "\u041e\u0431\u0435\u0434 \u0438 \u043e\u0442\u0434\u044b\u0445", "text": "\u0413\u043e\u0440\u044f\u0447\u0438\u0439 \u0441\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043e\u0431\u0435\u0434 \u0438 \u043f\u0440\u043e\u0433\u0443\u043b\u043a\u0430/\u0438\u0433\u0440\u044b \u043d\u0430 \u0441\u0432\u0435\u0436\u0435\u043c \u0432\u043e\u0437\u0434\u0443\u0445\u0435."}, {"title": "\u0410\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u0438\u0439 \u044f\u0437\u044b\u043a", "text": "\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0447\u0430\u0441\u044b \u0441 \u0443\u043f\u043e\u0440\u043e\u043c \u043d\u0430 \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u043d\u0443\u044e \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0443 (Speaking Club)."}, {"title": "\u0414\u043e\u043c\u0430\u0448\u043d\u0435\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0435", "text": "\u0421\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0439 \u0432 \u0448\u043a\u043e\u043b\u0435 \u043f\u043e\u0434 \u043f\u0440\u0438\u0441\u043c\u043e\u0442\u0440\u043e\u043c \u0443\u0447\u0438\u0442\u0435\u043b\u0435\u0439."}, {"title": "\u041a\u0440\u0443\u0436\u043a\u0438 \u0438 \u0441\u0435\u043a\u0446\u0438\u0438", "text": "\u0420\u043e\u0431\u043e\u0442\u043e\u0442\u0435\u0445\u043d\u0438\u043a\u0430, \u0448\u0430\u0445\u043c\u0430\u0442\u044b, \u0441\u043f\u043e\u0440\u0442, \u0436\u0438\u0432\u043e\u043f\u0438\u0441\u044c \u0438 \u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0430."}], "sections": {"why_title": "\u041f\u043e\u0447\u0435\u043c\u0443 Smart Start?", "why_subtitle": "\u041c\u044b \u0443\u0447\u0438\u043c \u0434\u0435\u0442\u0435\u0439 \u043c\u044b\u0441\u0