435\u043d\u0438\u043a\u043e\u0432 \u0448\u043a\u043e\u043b\u044b Smart Start.", "day_badge": "\u041e\u0434\u0438\u043d \u0434\u0435\u043d\u044c \u0432 Smart Start", "day_title": "\u0421 \u0443\u0442\u0440\u0430 \u0434\u043e \u0432\u0435\u0447\u0435\u0440\u0430 \u2014 \u0440\u0435\u0431\u0451\u043d\u043e\u043a \u0432 \u043d\u0430\u0434\u0451\u0436\u043d\u044b\u0445 \u0440\u0443\u043a\u0430\u0445", "day_text": "\u0420\u0435\u0436\u0438\u043c \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u0434\u043d\u044f: \u0443\u0440\u043e\u043a\u0438, \u043f\u0438\u0442\u0430\u043d\u0438\u0435, \u043e\u0442\u0434\u044b\u0445, \u0434\u043e\u043c\u0430\u0448\u043d\u0438\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u044f \u0438 \u043a\u0440\u0443\u0436\u043a\u0438 \u0432 \u043e\u0434\u043d\u043e\u043c \u0437\u0434\u0430\u043d\u0438\u0438. \u0412\u0435\u0447\u0435\u0440\u043e\u043c \u0432\u044b \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u0441\u043e \u0432\u0441\u0435\u043c\u0438 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u043c\u0438 \u0443\u0440\u043e\u043a\u0430\u043c\u0438.", "news_title": "\u0428\u043a\u043e\u043b\u044c\u043d\u0430\u044f \u0436\u0438\u0437\u043d\u044c", "results_kicker": "\u0414\u043b\u044f \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439", "results_title": "\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0430\u0448\u0438\u0445 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432", "results_text": "\u041a\u0430\u0436\u0434\u044b\u0439 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u2014 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0442\u0440\u0443\u0434\u0430 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0443\u0447\u0435\u043d\u0438\u043a\u0430. \u0412\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043a\u0430\u0436\u0434\u044b\u0439 \u0438\u0437 \u043d\u0438\u0445."}}','{"hero": {"badge": "Smart Start Private School \u00b7 Est. 2022", "admission_open": "Admissions open for the 2026\u20132027 academic year", "title": "Your Child''s Future Begins Today", "title_accent": "Today", "text": "Smart Start \u2014 modern education, intensive English, and individual attention for every child. Small class sizes, experienced faculty, and a secure environment.", "motto": "\u00abKnowledge bears true fruit only when paired with integrity\u00bb", "cta_primary": "Apply for Admission", "cta_secondary": "Campus Tour", "questions": "For inquiries:", "photo_caption": "Smart Start school building"}, "stats": [{"label": "students"}, {"label": "experienced teachers"}, {"label": "students per class at most"}, {"label": "educating future leaders since"}], "why": [{"title": "Small Class Sizes", "text": "Maximum 16-18 students per class \u2014 teachers know each child personally and adapt to their learning pace."}, {"title": "Intensive English", "text": "8-10 hours of English per week with dedicated IELTS and international exam preparation."}, {"title": "Full-Day Program", "text": "Lessons, teacher-supervised homework, clubs, and 3 hot nutritious meals daily."}, {"title": "Close Parent-Teacher Bond", "text": "Homeroom teachers regularly update parents on progress and challenges; parent meetings every term."}, {"title": "Safe & Secure Environment", "text": "CCTV surveillance, 24/7 security, a school doctor, and safe modern school transportation."}, {"title": "Recognized Certifications", "text": "IELTS, CEFR, SAT, and Olympiad achievements \u2014 each backed by the student''s real certificate."}], "cta": {"title": "Admissions open for 2027\u20132028", "text": "Places are limited \u2014 leave your application now and our manager will call you within one business day.", "button": "Apply now"}, "stages": [{"badge": "Primary School (Grades 1\u20134)", "title": "Foundation & Early Development", "ages": "Ages 7\u201310", "grades": "Grades 1\u20134", "text": "Literacy, speed reading, mental math, early English immersion, and creative thinking workshops.", "points": ["Literacy & speed reading", "Mental math & critical logic", "Early Oxford English program", "Small classes (max 18)"]}, {"badge": "Middle School (Grades 5\u20139)", "title": "Core Sciences & CEFR", "ages": "Ages 11\u201315", "grades": "Grades 5\u20139", "text": "Advanced mathematics, physics, and systematic preparation for national and international CEFR B2/C1 exams.", "points": ["Advanced Math & Physics", "Systematic CEFR B2/C1 prep", "STEM & Robotics Lab", "Olympiad competitions"]}, {"badge": "High School (Grades 10\u201311)", "title": "IELTS, SAT & College Admissions", "ages": "Ages 16\u201318", "grades": "Grades 10\u201311", "text": "IELTS 7.5+, SAT 1400+, and building a strong personal portfolio to win scholarships at top universities.", "points": ["IELTS 7.5+ & SAT 1400+ mastery", "Top-1000 University grants", "International portfolio building", "1-on-1 university counseling"]}], "day": [{"title": "Arrival & Breakfast", "text": "Warm welcome by faculty at the entrance followed by an energizing, wholesome breakfast."}, {"title": "Core Academic Classes", "text": "Engaging and interactive 45-minute lessons in small class settings."}, {"title": "Lunch & Recreation", "text": "Hot balanced lunch and supervised outdoor playtime."}, {"title": "Intensive English", "text": "Immersive sessions focused on conversation and Speaking Club practice."}, {"title": "Supervised Study", "text": "All homework completed at school under teacher supervision."}, {"title": "Clubs & Activities", "text": "Robotics, chess, athletics, visual arts, and mental math."}], "sections": {"why_title": "Why Smart Start?", "why_subtitle": "We teach children how to think, not just memorize \u2014 and you stay informed every step of the way.", "stages_title": "Academic Stages", "stages_text": "Curriculum tailored to the developmental and intellectual needs of each age group.", "teachers_title": "Who Teaches Your Child", "teachers_text": "A dedicated team of educators with extensive experience and internationally recognized credentials.", "testimonials_title": "What Parents Say", "testimonials_text": "Honest impressions from parents of students currently attending Smart Start.", "day_badge": "A Day at Smart Start", "day_title": "From Morning to Evening \u2014 In Trusted Hands", "day_text": "Full-day schedule: classes, meals, recreation, homework, and clubs under one roof. Pick up your child with homework done.", "news_title": "School Life", "results_kicker": "For Parents", "results_title": "Our Students'' Results", "results_text": "Every certificate reflects a real student''s hard work. You can verify each one."}}','Smart Start — xususiy maktab, Toshkent','Smart Start — частная школа, Ташкент','Smart Start — Private School in Tashkent','Farzandingizning kelajagi bugun boshlanadi. Zamonaviy ta''lim, kuchli ingliz tili, kichik sinflar va tajribali o''qituvchilar. 2026–2027 o''quv yiliga qabul ochiq.','Будущее вашего ребёнка начинается сегодня. Современное образование, сильный английский, небольшие классы и опытные педагоги.','Your child''s future begins today. Modern education, strong English, small classes and experienced teachers.',1,'2026-11-07 10:05:26.480277');INSERT INTO "pages" VALUES(2,'about','{"title": "Maktab haqida", "story": "Smart Start 2022-yilda bir maqsad bilan ochilgan: bolalarga yod olishni emas, fikrlashni o''rgatish. Bugun maktabimizda 300 dan ortiq o''quvchi tahsil oladi.", "mission": "Har bir bolaning qobiliyatini ochish va uni zamonaviy dunyoda ishonch bilan yashashga tayyorlash.", "values_title": "Qadriyatlarimiz", "values": ["Hurmat", "Qiziquvchanlik", "Mas''uliyat", "Halollik"], "founded_year": 2022, "image": 3}','{"title": "\u041e \u0448\u043a\u043e\u043b\u0435", "story": "Smart Start \u043e\u0442\u043a\u0440\u044b\u043b\u0430\u0441\u044c \u0432 2022 \u0433\u043e\u0434\u0443 \u0441 \u043e\u0434\u043d\u043e\u0439 \u0446\u0435\u043b\u044c\u044e: \u0443\u0447\u0438\u0442\u044c \u0434\u0435\u0442\u0435\u0439 \u043d\u0435 \u0437\u0443\u0431\u0440\u0438\u0442\u044c, \u0430 \u0434\u0443\u043c\u0430\u0442\u044c. \u0421\u0435\u0433\u043e\u0434\u043d\u044f \u0432 \u043d\u0430\u0448\u0435\u0439 \u0448\u043a\u043e\u043b\u0435 \u0443\u0447\u0430\u0442\u0441\u044f \u0431\u043e\u043b\u0435\u0435 300 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432.", "mission": "\u0420\u0430\u0441\u043a\u0440\u044b\u0442\u044c \u0441\u043f\u043e\u0441\u043e\u0431\u043d\u043e\u0441\u0442\u0438 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c \u0435\u0433\u043e \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e \u0436\u0438\u0442\u044c \u0432 \u0441\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u043c \u043c\u0438\u0440\u0435.", "values_title": "\u041d\u0430\u0448\u0438 \u0446\u0435\u043d\u043d\u043e\u0441\u0442\u0438", "values": ["\u0423\u0432\u0430\u0436\u0435\u043d\u0438\u0435", "\u041b\u044e\u0431\u043e\u0437\u043d\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c", "\u041e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c", "\u0427\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c"]}','{"title": "About the School", "story": "Smart Start opened in 2022 with one goal: to teach children to think, not to memorize. Today more than 300 students study at our school.", "mission": "To unlock every child''s potential and prepare them to live confidently in the modern world.", "values_title": "Our Values", "values": ["Respect", "Curiosity", "Responsibility", "Honesty"]}','Maktab haqida','О школе','About','Smart Start 2022-yilda ochilgan: bolalarga yod olishni emas, fikrlashni o''rgatamiz.','Smart Start открылась в 2022 году: мы учим детей думать, а не зубрить.','Smart Start opened in 2022: we teach children to think, not to memorize.',3,'2026-11-07 10:05:26.480280');INSERT INTO "pages" VALUES(3,'admission','{"title": "Qabul 4 qadamda", "text": "Joylar soni cheklangan. Arizangizni qoldiring \u2014 menejerimiz 1 ish kuni ichida qo''ng''iroq qiladi va maktabga tanishuvga taklif qiladi.", "steps": [{"title": "Ariza qoldiring", "text": "Saytda yoki telefon orqali."}, {"title": "Tanishuv", "text": "Maktabga keling, sinflar va o''qituvchilar bilan tanishing."}, {"title": "Diagnostik suhbat", "text": "Farzandingiz bilimini aniqlaymiz (imtihon emas, qo''rqmaslik kerak)."}, {"title": "Shartnoma", "text": "Hujjatlarni topshirib, o''qishni boshlaysiz."}], "documents_title": "Kerakli hujjatlar", "documents": ["Tug''ilganlik guvohnomasi nusxasi", "Tibbiy ma''lumotnoma (086-shakl)", "3x4 rasm (4 dona)", "Ota-ona pasporti nusxasi", "Oldingi maktabdan tabel (2-sinfdan boshlab)"], "faq_title": "Ko''p beriladigan savollar", "prices_title": "O''qish narxlari"}','{"title": "\u041f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0435 \u0432 4 \u0448\u0430\u0433\u0430", "text": "\u041a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043c\u0435\u0441\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043e. \u041e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0437\u0430\u044f\u0432\u043a\u0443 \u2014 \u043d\u0430\u0448 \u043c\u0435\u043d\u0435\u0434\u0436\u0435\u0440 \u043f\u0435\u0440\u0435\u0437\u0432\u043e\u043d\u0438\u0442 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 1 \u0440\u0430\u0431\u043e\u0447\u0435\u0433\u043e \u0434\u043d\u044f \u0438 \u043f\u0440\u0438\u0433\u043b\u0430\u0441\u0438\u0442 \u043d\u0430 \u0437\u043d\u0430\u043a\u043e\u043c\u0441\u0442\u0432\u043e \u0441\u043e \u0448\u043a\u043e\u043b\u043e\u0439.", "steps": [{"title": "\u041e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0437\u0430\u044f\u0432\u043a\u0443", "text": "\u041d\u0430 \u0441\u0430\u0439\u0442\u0435 \u0438\u043b\u0438 \u043f\u043e \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0443."}, {"title": "\u0417\u043d\u0430\u043a\u043e\u043c\u0441\u0442\u0432\u043e", "text": "\u041f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0435 \u0432 \u0448\u043a\u043e\u043b\u0443, \u043f\u043e\u0437\u043d\u0430\u043a\u043e\u043c\u044c\u0442\u0435\u0441\u044c \u0441 \u043a\u043b\u0430\u0441\u0441\u0430\u043c\u0438 \u0438 \u0443\u0447\u0438\u0442\u0435\u043b\u044f\u043c\u0438."}, {"title": "\u0414\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0431\u0435\u0441\u0435\u0434\u0430", "text": "\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u043c \u0437\u043d\u0430\u043d\u0438\u044f \u0440\u0435\u0431\u0451\u043d\u043a\u0430 (\u044d\u0442\u043e \u043d\u0435 \u044d\u043a\u0437\u0430\u043c\u0435\u043d, \u0431\u043e\u044f\u0442\u044c\u0441\u044f \u043d\u0435 \u043d\u0443\u0436\u043d\u043e)."}, {"title": "\u0414\u043e\u0433\u043e\u0432\u043e\u0440", "text": "\u0421\u0434\u0430\u0451\u0442\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b \u0438 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0435 \u0443\u0447\u0451\u0431\u0443."}], "documents_title": "\u041d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u0435 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b", "documents": ["\u041a\u043e\u043f\u0438\u044f \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438", "\u041c\u0435\u0434\u0438\u0446\u0438\u043d\u0441\u043a\u0430\u044f \u0441\u043f\u0440\u0430\u0432\u043a\u0430 (\u0444\u043e\u0440\u043c\u0430 086)", "\u0424\u043e\u0442\u043e 3x4 (4 \u0448\u0442.)", "\u041a\u043e\u043f\u0438\u044f \u043f\u0430\u0441\u043f\u043e\u0440\u0442\u0430 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f", "\u0422\u0430\u0431\u0435\u043b\u044c \u0438\u0437 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u0439 \u0448\u043a\u043e\u043b\u044b (\u0441\u043e 2 \u043a\u043b\u0430\u0441\u0441\u0430)"], "faq_title": "\u0427\u0430\u0441\u0442\u044b\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u044b", "prices_title": "\u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f"}','{"title": "Admission in 4 Steps", "text": "Places are limited. Leave an application \u2014 our manager will call you within one business day and invite you to visit the school.", "steps": [{"title": "Apply", "text": "Online or by phone."}, {"title": "Visit", "text": "Come to the school and meet the classes and teachers."}, {"title": "Diagnostic chat", "text": "We assess your child''s knowledge (not an exam \u2014 nothing to fear)."}, {"title": "Contract", "text": "Submit the documents and start studying."}], "documents_title": "Required documents", "documents": ["Copy of the birth certificate", "Medical certificate (form 086)", "3x4 photos (4 pcs)", "Copy of a parent''s passport", "Report card from the previous school (from grade 2)"], "faq_title": "Frequently Asked Questions", "prices_title": "Tuition"}','Qabul','Поступление','Admissions','Qabul 4 qadamda: ariza, tanishuv, diagnostik suhbat va shartnoma. Kerakli hujjatlar va narxlar.','Поступление в 4 шага: заявка, знакомство, диагностическая беседа и договор.','Admission in 4 steps: application, visit, diagnostic chat and contract.',2,'2026-11-07 10:05:26.480280');INSERT INTO "pages" VALUES(4,'contact','{"title": "Biz bilan bog''laning", "text": "Savolingiz bormi? Qo''ng''iroq qiling, Telegram''da yozing yoki maktabga keling \u2014 sizni choy bilan kutib olamiz.", "address": "120100, Sirdaryo viloyati, Guliston, Al-Xorazmiy ko\u2018chasi, 36", "phones": ["+998 98 560 07 20"], "telegram": "https://t.me/stmartstartt_bot", "instagram": "", "hours": "Du\u2013Ju: 08:30\u201317:30, Sha: 08:30\u201312:00", "map_embed_url": "https://maps.google.com/maps?q=120100,+Sirdaryo+viloyati,+Guliston,+Al-Xorazmiy+ko''chasi,+36&z=16&hl=uz&output=embed", "lat": 40.49, "lng": 68.783}','{"title": "\u0421\u0432\u044f\u0436\u0438\u0442\u0435\u0441\u044c \u0441 \u043d\u0430\u043c\u0438", "text": "\u0415\u0441\u0442\u044c \u0432\u043e\u043f\u0440\u043e\u0441\u044b? \u041f\u043e\u0437\u0432\u043e\u043d\u0438\u0442\u0435, \u043d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0432 Telegram \u0438\u043b\u0438 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442\u0435 \u0432 \u0448\u043a\u043e\u043b\u0443 \u2014 \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u043c \u0432\u0430\u0441 \u0441 \u0447\u0430\u0435\u043c.", "address": "120100, Sirdaryo viloyati, Guliston, Al-Xorazmiy ko\u2018chasi, 36", "hours": "\u041f\u043d\u2013\u041f\u0442: 08:30\u201317:30, \u0421\u0431: 08:30\u201312:00", "phones": ["+998 98 560 07 20"], "map_embed_url": "https://maps.google.com/maps?q=120100,+Sirdaryo+viloyati,+Guliston,+Al-Xorazmiy+ko''chasi,+36&z=16&hl=uz&output=embed", "lat": 40.49, "lng": 68.783}','{"title": "Contact Us", "text": "Have a question? Call us, message us on Telegram or visit the school \u2014 we''ll welcome you with a cup of tea.", "address": "120100, Sirdaryo viloyati, Guliston, Al-Xorazmiy ko\u2018chasi, 36", "hours": "Mon\u2013Fri: 08:30\u201317:30, Sat: 08:30\u201312:00", "phones": ["+998 98 560 07 20"], "map_embed_url": "https://maps.google.com/maps?q=120100,+Sirdaryo+viloyati,+Guliston,+Al-Xorazmiy+ko''chasi,+36&z=16&hl=uz&output=embed", "lat": 40.49, "lng": 68.783}','Aloqa','Контакты','Contact','Smart Start: Guliston, Al-Xorazmiy ko‘chasi, 36. Telefon +998 98 560 07 20. Du–Ju 08:30–17:30, Sha 08:30–12:00.','Smart Start: Ташкент, Чиланзарский район. Телефон +998 90 994 74 07.','Smart Start: Chilanzar district, Tashkent. Phone +998 90 994 74 07.',NULL,'2026-11-07 10:05:26.480281');INSERT INTO "pages" VALUES(5,'privacy','{"title": "Maxfiylik siyosati", "updated": "2026-11-07", "body": "<p>Smart Start xususiy maktabi (keyingi o''rinlarda \u2014 \u00abMaktab\u00bb) sayt orqali yuborilgan shaxsiy ma''lumotlarni O''zbekiston Respublikasining \u00abShaxsga doir ma''lumotlar to''g''risida\u00bbgi qonuniga muvofiq qayta ishlaydi.</p><h3>Qanday ma''lumotlarni yig''amiz</h3><ul><li>Ota-onaning ismi va telefon raqami;</li><li>farzandning ismi, tug''ilgan yili va qabul qilinmoqchi bo''lgan sinfi;</li><li>formada qoldirilgan izoh, reklama manbasi (UTM).</li></ul><h3>Nima uchun</h3><p>Faqat qabul arizasini ko''rib chiqish, siz bilan bog''lanish va ekskursiyaga yozish uchun.</p><h3>Saqlash</h3><p>Ma''lumotlar O''zbekiston hududidagi serverda saqlanadi va faqat ruxsati bor maktab xodimlariga ko''rinadi. Uchinchi shaxslarga sotilmaydi va berilmaydi.</p><h3>O''quvchilar sertifikatlari</h3><p>Saytda faqat ota-onasi yozma rozilik bergan o''quvchilarning sertifikatlari e''lon qilinadi; hujjat raqamlari va pasport ma''lumotlari yashiriladi.</p><h3>Huquqlaringiz</h3><p>Ma''lumotlaringizni ko''rish, tuzatish yoki o''chirishni so''rash uchun +998 98 560 07 20 raqamiga qo''ng''iroq qiling.</p>"}','{"title": "\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438", "updated": "2026-11-07", "body": "<p>\u0427\u0430\u0441\u0442\u043d\u0430\u044f \u0448\u043a\u043e\u043b\u0430 Smart Start (\u00ab\u0428\u043a\u043e\u043b\u0430\u00bb) \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435, \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0435 \u0447\u0435\u0440\u0435\u0437 \u0441\u0430\u0439\u0442, \u0432 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0441 \u0417\u0430\u043a\u043e\u043d\u043e\u043c \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u0423\u0437\u0431\u0435\u043a\u0438\u0441\u0442\u0430\u043d \u00ab\u041e \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445\u00bb.</p><h3>\u041a\u0430\u043a\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043c\u044b \u0441\u043e\u0431\u0438\u0440\u0430\u0435\u043c</h3><ul><li>\u0418\u043c\u044f \u0438 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f;</li><li>\u0438\u043c\u044f \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u0433\u043e\u0434 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0438 \u043a\u043b\u0430\u0441\u0441 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u044f;</li><li>\u043a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0439 \u0438\u0437 \u0444\u043e\u0440\u043c\u044b \u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0440\u0435\u043a\u043b\u0430\u043c\u044b (UTM).</li></ul><h3>\u0417\u0430\u0447\u0435\u043c</h3><p>\u0422\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u0438\u044f \u0437\u0430\u044f\u0432\u043a\u0438, \u0441\u0432\u044f\u0437\u0438 \u0441 \u0432\u0430\u043c\u0438 \u0438 \u0437\u0430\u043f\u0438\u0441\u0438 \u043d\u0430 \u044d\u043a\u0441\u043a\u0443\u0440\u0441\u0438\u044e.</p><h3>\u0425\u0440\u0430\u043d\u0435\u043d\u0438\u0435</h3><p>\u0414\u0430\u043d\u043d\u044b\u0435 \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u043d\u0430 \u0441\u0435\u0440\u0432\u0435\u0440\u0435 \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0423\u0437\u0431\u0435\u043a\u0438\u0441\u0442\u0430\u043d\u0430 \u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0442\u043e\u043b\u044c\u043a\u043e \u0443\u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0435\u043d\u043d\u044b\u043c \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u0430\u043c \u0448\u043a\u043e\u043b\u044b. \u041c\u044b \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0451\u043c \u0438 \u043d\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u043c \u0438\u0445 \u0442\u0440\u0435\u0442\u044c\u0438\u043c \u043b\u0438\u0446\u0430\u043c.</p><h3>\u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u044b \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432</h3><p>\u041d\u0430 \u0441\u0430\u0439\u0442\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u044b \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432 \u0441 \u043f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u043e\u0433\u043e \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u044f \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439; \u043d\u043e\u043c\u0435\u0440\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u043e\u0432 \u0438 \u043f\u0430\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0441\u043a\u0440\u044b\u0432\u0430\u044e\u0442\u0441\u044f.</p><h3>\u0412\u0430\u0448\u0438 \u043f\u0440\u0430\u0432\u0430</h3><p>\u0427\u0442\u043e\u0431\u044b \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c, \u0438\u0441\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0438\u043b\u0438 \u0443\u0434\u0430\u043b\u0438\u0442\u044c \u0441\u0432\u043e\u0438 \u0434\u0430\u043d\u043d\u044b\u0435, \u043f\u043e\u0437\u0432\u043e\u043d\u0438\u0442\u0435 \u043f\u043e \u043d\u043e\u043c\u0435\u0440\u0443 +998 98 560 07 20.</p>"}','{"title": "Privacy Policy", "updated": "2026-11-07", "body": "<p>Smart Start Private School (the \u201cSchool\u201d) processes personal data submitted through this website in accordance with the Law of the Republic of Uzbekistan \u201cOn Personal Data\u201d.</p><h3>What we collect</h3><ul><li>Parent''s name and phone number;</li><li>child''s name, year of birth and target grade;</li><li>the comment left in the form and the advertising source (UTM).</li></ul><h3>Why</h3><p>Only to review the application, contact you and book school tours.</p><h3>Storage</h3><p>Data is stored on a server located in Uzbekistan and is visible only to authorised school staff. We never sell or share it with third parties.</p><h3>Student certificates</h3><p>Only certificates of students whose parents gave written consent are published; document numbers and passport details are hidden.</p><h3>Your rights</h3><p>To view, correct or delete your data, call +998 98 560 07 20.</p>"}','Maxfiylik siyosati','Политика конфиденциальности','Privacy Policy','Shaxsiy ma''lumotlarni qayta ishlash tartibi.','Порядок обработки персональных данных.','How we process personal data.',NULL,'2026-11-07 10:05:26.480281');INSERT INTO "pages" VALUES(6,'thanks','{"title": "Rahmat! Arizangiz qabul qilindi.", "text": "Menejerimiz 1 ish kuni ichida siz bilan bog''lanadi. Kutish vaqtida Instagram va Telegram kanalimizdan maktab hayotini kuzatib boring.", "button": "Bosh sahifaga qaytish"}','{"title": "\u0421\u043f\u0430\u0441\u0438\u0431\u043e! \u0412\u0430\u0448\u0430 \u0437\u0430\u044f\u0432\u043a\u0430 \u043f\u0440\u0438\u043d\u044f\u0442\u0430.", "text": "\u041d\u0430\u0448 \u043c\u0435\u043d\u0435\u0434\u0436\u0435\u0440 \u0441\u0432\u044f\u0436\u0435\u0442\u0441\u044f \u0441 \u0432\u0430\u043c\u0438 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 1 \u0440\u0430\u0431\u043e\u0447\u0435\u0433\u043e \u0434\u043d\u044f. \u041f\u043e\u043a\u0430 \u0436\u0434\u0451\u0442\u0435 \u2014 \u0441\u043b\u0435\u0434\u0438\u0442\u0435 \u0437\u0430 \u0436\u0438\u0437\u043d\u044c\u044e \u0448\u043a\u043e\u043b\u044b \u0432 \u043d\u0430\u0448\u0435\u043c Instagram \u0438 Telegram-\u043a\u0430\u043d\u0430\u043b\u0435.", "button": "\u0412\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u043d\u0430 \u0433\u043b\u0430\u0432\u043d\u0443\u044e"}','{"title": "Thank you! Your application has been received.", "text": "Our manager will contact you within one business day. Meanwhile, follow school life on our Instagram and Telegram channel.", "button": "Back to home"}','Rahmat','Спасибо','Thank you','Arizangiz qabul qilindi.','Ваша заявка принята.','Your application has been received.',NULL,'2026-11-07 10:05:26.480282');INSERT INTO "pages" VALUES(7,'results','{"title": "O''quvchilarimiz natijalari", "text": "Har bir sertifikat \u2014 haqiqiy o''quvchi va haqiqiy mehnat. Natijalarni o''zingiz tekshirib ko''rishingiz mumkin.", "stats_labels": {"ielts_7_plus": "ta IELTS 7.0+", "cefr_b2_c1": "ta CEFR B2\u2013C1", "olympiad_winners": "olimpiada g''olibi", "sat_1300_plus": "ta SAT 1300+"}, "cta_title": "Farzandingiz ham shunday natijaga erishishini xohlaysizmi?", "cta_button": "Qabulga yoziling", "privacy_note": "Saytda faqat ota-onasi yozma rozilik bergan o''quvchilarning sertifikatlari ko''rsatiladi."}','{"title": "\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0430\u0448\u0438\u0445 \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432", "text": "\u041a\u0430\u0436\u0434\u044b\u0439 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u2014 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0443\u0447\u0435\u043d\u0438\u043a \u0438 \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0440\u0443\u0434. \u0412\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0441\u0430\u043c\u0438.", "stats_labels": {"ielts_7_plus": "IELTS 7.0+", "cefr_b2_c1": "CEFR B2\u2013C1", "olympiad_winners": "\u043f\u043e\u0431\u0435\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043e\u043b\u0438\u043c\u043f\u0438\u0430\u0434", "sat_1300_plus": "SAT 1300+"}, "cta_title": "\u0425\u043e\u0442\u0438\u0442\u0435, \u0447\u0442\u043e\u0431\u044b \u0432\u0430\u0448 \u0440\u0435\u0431\u0451\u043d\u043e\u043a \u0434\u043e\u0431\u0438\u043b\u0441\u044f \u0442\u0430\u043a\u0438\u0445 \u0436\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432?", "cta_button": "\u0417\u0430\u043f\u0438\u0441\u0430\u0442\u044c\u0441\u044f \u043d\u0430 \u043f\u0440\u0438\u0451\u043c", "privacy_note": "\u041d\u0430 \u0441\u0430\u0439\u0442\u0435 \u043f\u0443\u0431\u043b\u0438\u043a\u0443\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u044b \u0443\u0447\u0435\u043d\u0438\u043a\u043e\u0432, \u0447\u044c\u0438 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u0434\u0430\u043b\u0438 \u043f\u0438\u0441\u044c\u043c\u0435\u043d\u043d\u043e\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435."}','{"title": "Our Students'' Results", "text": "Every certificate is a real student and real effort. You can verify the results yourself.", "stats_labels": {"ielts_7_plus": "IELTS 7.0+", "cefr_b2_c1": "CEFR B2\u2013C1", "olympiad_winners": "Olympiad winners", "sat_1300_plus": "SAT 1300+"}, "cta_title": "Want your child to achieve results like these?", "cta_button": "Apply now", "privacy_note": "Only certificates of students whose parents gave written consent are shown on the site."}','O''quvchilarimiz natijalari','Результаты учеников','Student Results','IELTS, CEFR, SAT va fan olimpiadalari bo''yicha Smart Start o''quvchilarining haqiqiy sertifikatlari.','Подлинные сертификаты учеников Smart Start: IELTS, CEFR, SAT и олимпиады.','Real certificates of Smart Start students: IELTS, CEFR, SAT and Olympiads.',NULL,'2026-11-07 10:05:26.480282');INSERT INTO "pages" VALUES(8,'partners','{"title": "Dunyoning top-1000 universitetlari bilan hamkorlik", "text": "Smart Start QS World University Rankings bo''yicha top-1000 talikka kiruvchi 6 ta xorijiy universitet bilan hamkorlik qiladi. Bu hamkorlik bitiruvchilarimizga qabulda tavsiya, yozgi maktablar va grantlar imkonini beradi.", "benefits": ["Qabulda to''g''ridan-to''g''ri tavsiya", "Yozgi maktab yoki onlayn xalqaro kurslar", "Xalqaro grant yoki chegirma imkoniyatlari"]}','{"title": "\u0421\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u0441 \u0442\u043e\u043f-1000 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0438\u0442\u0435\u0442\u0430\u043c\u0438 \u043c\u0438\u0440\u0430", "text": "Smart Start \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u0447\u0430\u0435\u0442 \u0441 6 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u043c\u0438 \u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0438\u0442\u0435\u0442\u0430\u043c\u0438 \u0438\u0437 \u0442\u043e\u043f-1000 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0430 QS World University Rankings. \u042d\u0442\u043e \u0434\u0430\u0451\u0442 \u043d\u0430\u0448\u0438\u043c \u0432\u044b\u043f\u0443\u0441\u043a\u043d\u0438\u043a\u0430\u043c \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u0438 \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0438, \u043b\u0435\u0442\u043d\u0438\u0435 \u0448\u043a\u043e\u043b\u044b \u0438 \u0433\u0440\u0430\u043d\u0442\u044b.", "benefits": ["\u041f\u0440\u044f\u043c\u0430\u044f \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u044f \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0438", "\u041b\u0435\u0442\u043d\u0438\u0435 \u0448\u043a\u043e\u043b\u044b \u0438 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u044b\u0435 \u043e\u043d\u043b\u0430\u0439\u043d-\u043a\u0443\u0440\u0441\u044b", "\u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0433\u0440\u0430\u043d\u0442\u043e\u0432 \u0438 \u0441\u043a\u0438\u0434\u043e\u043a"]}','{"title": "Partnership with the World''s Top-1000 Universities", "text": "Smart Start partners with 6 international universities ranked in the QS World University Rankings top 1000. This gives our graduates admission recommendations, summer schools and scholarships.", "benefits": ["Direct recommendation for admission", "Summer schools and international online courses", "Scholarship and tuition discount opportunities"]}','Hamkor universitetlar','Вузы-партнёры','Partner Universities','QS reytingidagi top-1000 universitetlar bilan hamkorlik.','Сотрудничество с университетами из топ-1000 рейтинга QS.','Partnership with QS top-1000 universities.',NULL,'2026-11-07 10:05:26.480282');CREATE TABLE partners (
	id INTEGER NOT NULL, 
