	country_uz VARCHAR(100) NOT NULL, 
	country_ru VARCHAR(100) NOT NULL, 
	country_en VARCHAR(100) NOT NULL, 
	country_code VARCHAR(2) NOT NULL, 
	logo_id INTEGER, 
	qs_rank INTEGER, 
	qs_year INTEGER, 
	description_uz TEXT NOT NULL, 
	description_ru TEXT NOT NULL, 
	description_en TEXT NOT NULL, 
	website_url VARCHAR(300) NOT NULL, 
	lat FLOAT, 
	lng FLOAT, 
	"order" INTEGER NOT NULL, 
	is_visible BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(logo_id) REFERENCES media (id) ON DELETE SET NULL
);INSERT INTO "partners" VALUES(1,'Oxford International College','Buyuk Britaniya','Великобритания','United Kingdom','GB',12,NULL,2025,'Hamkorlik: qabulda tavsiya, yozgi maktab va grant imkoniyatlari.','Сотрудничество: рекомендация при поступлении, летние школы и гранты.','Partnership: admission recommendation, summer schools and scholarships.','',51.752,-1.2577,0,1,'2026-11-07 10:05:27.072744');INSERT INTO "partners" VALUES(2,'Technical University of Munich (TUM)','Germaniya','Германия','Germany','DE',13,28,2025,'Hamkorlik: qabulda tavsiya, yozgi maktab va grant imkoniyatlari.','Сотрудничество: рекомендация при поступлении, летние школы и гранты.','Partnership: admission recommendation, summer schools and scholarships.','https://www.tum.de',48.1497,11.5679,1,1,'2026-11-07 10:05:27.166516');INSERT INTO "partners" VALUES(3,'KAIST','Janubiy Koreya','Южная Корея','South Korea','KR',14,56,2025,'Hamkorlik: qabulda tavsiya, yozgi maktab va grant imkoniyatlari.','Сотрудничество: рекомендация при поступлении, летние школы и гранты.','Partnership: admission recommendation, summer schools and scholarships.','https://www.kaist.ac.kr',36.3721,127.3604,2,1,'2026-11-07 10:05:27.281551');INSERT INTO "partners" VALUES(4,'University of Bristol','Buyuk Britaniya','Великобритания','United Kingdom','GB',15,54,2025,'Hamkorlik: qabulda tavsiya, yozgi maktab va grant imkoniyatlari.','Сотрудничество: рекомендация при поступлении, летние школы и гранты.','Partnership: admission recommendation, summer schools and scholarships.','https://www.bristol.ac.uk',51.4585,-2.603,3,1,'2026-11-07 10:05:27.374609');INSERT INTO "partners" VALUES(5,'Politecnico di Milano','Italiya','Италия','Italy','IT',16,111,2025,'Hamkorlik: qabulda tavsiya, yozgi maktab va grant imkoniyatlari.','Сотрудничество: рекомендация при поступлении, летние школы и гранты.','Partnership: admission recommendation, summer schools and scholarships.','https://www.polimi.it',45.4781,9.2272,4,1,'2026-11-07 10:05:27.476494');INSERT INTO "partners" VALUES(6,'University of Warsaw','Polsha','Польша','Poland','PL',17,262,2025,'Hamkorlik: qabulda tavsiya, yozgi maktab va grant imkoniyatlari.','Сотрудничество: рекомендация при поступлении, летние школы и гранты.','Partnership: admission recommendation, summer schools and scholarships.','https://www.uw.edu.pl',52.2403,21.0189,5,1,'2026-11-07 10:05:27.652418');CREATE TABLE posts (
	id INTEGER NOT NULL, 
	type VARCHAR(10) NOT NULL, 
	slug VARCHAR(120) NOT NULL, 
	title_uz VARCHAR(300) NOT NULL, 
	title_ru VARCHAR(300) NOT NULL, 
	title_en VARCHAR(300) NOT NULL, 
	excerpt_uz VARCHAR(500) NOT NULL, 
	excerpt_ru VARCHAR(500) NOT NULL, 
	excerpt_en VARCHAR(500) NOT NULL, 
	body_uz TEXT NOT NULL, 
	body_ru TEXT NOT NULL, 
	body_en TEXT NOT NULL, 
	cover_id INTEGER, 
	event_date DATETIME, 
	event_location VARCHAR(300) NOT NULL, 
	published_at DATETIME, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(cover_id) REFERENCES media (id) ON DELETE SET NULL
);INSERT INTO "posts" VALUES(1,'event','ochiq-eshiklar-kuni-mart-2026','Ochiq eshiklar kuni — maktabimiz bilan tanishing','День открытых дверей — познакомьтесь со школой','Open House Day — Discover Our Campus','Ota-onalar uchun maktab bo''ylab ekskursiya, ustozlar bilan ochiq muloqot va namunaviy darslar.','Экскурсия для родителей по школе, открытый диалог с учителями и показательные уроки.','Campus tour for prospective families, open dialogue with faculty, and demonstration lessons.','<p>15-mart kuni Smart Start ochiq eshiklar kunini o''tkazadi. Ota-onalar maktab bo''ylab ekskursiyada sinflar, laboratoriya va oshxona bilan tanishadi.</p><p>Ustozlar bilan ochiq muloqot va namunaviy darslar bo''lib o''tadi. Farzandingiz bilan keling — bolalar uchun alohida mashg''ulotlar tayyorlaymiz.</p>','<p>15 марта Smart Start проводит день открытых дверей. Родители познакомятся с классами, лабораторией и столовой.</p><p>Вас ждут открытый диалог с учителями и показательные уроки. Приходите с ребёнком — для детей подготовлены отдельные занятия.</p>','<p>On March 15 Smart Start hosts an Open House Day. Parents will tour the classrooms, the lab and the canteen.</p><p>Meet our teachers and attend demonstration lessons. Bring your child — we have special activities for kids.</p>',2,'2026-03-15 05:00:00.000000','Toshkent, Chilonzor tumani, Bunyodkor shoh ko''chasi','2026-03-01 04:00:00.000000','2026-11-07 10:05:37.165437','2026-11-07 10:05:37.165439');INSERT INTO "posts" VALUES(2,'news','tuman-olimpiadasida-golib','O''quvchimiz tuman olimpiadasida g''olib bo''ldi','Наши ученики победили на районной олимпиаде','Our Students Triumphed at the District Olympiad','Matematika va ingliz tili yo''nalishida 5 nafar o''quvchimiz faxrli 1 va 2-o''rinlarni egalladi.','5 наших учеников заняли призовые 1 и 2 места по математике и английскому языку.','5 of our students secured 1st and 2nd places in mathematics and English competitions.','<p>Tuman fan olimpiadasida matematika va ingliz tili yo''nalishida 5 nafar o''quvchimiz faxrli 1 va 2-o''rinlarni egalladi.</p><p>G''oliblarni va ularning ustozlarini tabriklaymiz! Endi ular shahar bosqichiga tayyorlanmoqda.</p>','<p>На районной предметной олимпиаде 5 наших учеников заняли призовые 1 и 2 места по математике и английскому языку.</p><p>Поздравляем победителей и их учителей! Теперь ребята готовятся к городскому этапу.</p>','<p>At the district subject Olympiad, 5 of our students won 1st and 2nd places in mathematics and English.</p><p>Congratulations to the winners and their teachers! They are now preparing for the city round.</p>',3,NULL,'','2026-02-28 07:00:00.000000','2026-11-07 10:05:37.165439','2026-11-07 10:05:37.165439');INSERT INTO "posts" VALUES(3,'news','qishki-tatil-jadvali-va-togaraklar','Qishki ta''til jadvali va qo''shimcha to''garaklar','Расписание зимних каникул и факультативов','Winter Break Schedule & Special Workshops','Robototexnika va shaxmat bo''yicha qishki oromgoh dasturi tasdiqlandi.','Утверждена программа зимнего интенсива по робототехнике и шахматам.','Winter intensive camp program for robotics and chess has been announced.','<p>Qishki ta''til davomida robototexnika va shaxmat bo''yicha qishki oromgoh dasturi tasdiqlandi.</p><p>Mashg''ulotlar maktab binosida, o''qituvchilar nazoratida o''tadi. Ro''yxatdan o''tish uchun sinf rahbariga murojaat qiling.</p>','<p>На зимние каникулы утверждена программа интенсива по робототехнике и шахматам.</p><p>Занятия проходят в здании школы под присмотром учителей. Для записи обратитесь к классному руководителю.</p>','<p>A winter intensive camp program for robotics and chess has been approved for the holidays.</p><p>Sessions take place at school under teacher supervision. Contact your homeroom teacher to sign up.</p>',5,NULL,'','2026-01-10 05:00:00.000000','2026-11-07 10:05:37.165440','2026-11-07 10:05:37.165440');INSERT INTO "posts" VALUES(4,'event','ochiq-eshiklar-kuni-qabul-2027','Ochiq eshiklar kuni: 2026–2027 o''quv yiliga qabul','День открытых дверей: приём на 2026–2027 учебный год','Open Day: Admissions for 2026–2027','Maktab bo''ylab ekskursiya, ustozlar bilan suhbat va qabul shartlari haqida savol-javob.','Экскурсия по школе, беседа с учителями и ответы на вопросы о приёме.','School tour, meet the teachers and get answers about admission.','<p>2026–2027 o''quv yiliga qabul boshlandi. Ochiq eshiklar kunida maktab bilan tanishing, ustozlar bilan suhbatlashing va qabul shartlari haqida savollaringizga javob oling.</p><p>Joylar cheklangan — saytda oldindan yoziling.</p>','<p>Начался приём на 2026–2027 учебный год. Приходите на день открытых дверей: познакомьтесь со школой и учителями, задайте вопросы о приёме.</p><p>Количество мест ограничено — запишитесь заранее на сайте.</p>','<p>Admissions for 2026–2027 are open. Visit our Open Day to see the school, meet the teachers and ask about admission.</p><p>Places are limited — book in advance on the website.</p>',1,'2026-11-14 05:00:00.000000','Toshkent, Chilonzor tumani, Bunyodkor shoh ko''chasi','2026-11-06 10:05:37.163909','2026-11-07 10:05:37.165440','2026-11-07 10:05:37.165441');CREATE TABLE prices (
	id INTEGER NOT NULL, 
	grade_range VARCHAR(50) NOT NULL, 
	monthly_fee INTEGER NOT NULL, 
	meals_fee INTEGER NOT NULL, 
	transport_fee INTEGER NOT NULL, 
	note_uz VARCHAR(500) NOT NULL, 
	note_ru VARCHAR(500) NOT NULL, 
	note_en VARCHAR(500) NOT NULL, 
	"order" INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);INSERT INTO "prices" VALUES(1,'1–4',4500000,900000,500000,'Ikkinchi farzand uchun 10% chegirma','Скидка 10% на второго ребёнка','10% discount for the second child',0,'2026-11-07 10:05:27.652956');INSERT INTO "prices" VALUES(2,'5–9',5200000,900000,500000,'Ingliz tili va to''garaklar narxga kiradi','Английский и кружки включены в стоимость','English and clubs are included',1,'2026-11-07 10:05:27.652957');INSERT INTO "prices" VALUES(3,'10–11',5900000,900000,500000,'IELTS/SAT tayyorlovi narxga kiradi','Подготовка к IELTS/SAT включена','IELTS/SAT preparation is included',2,'2026-11-07 10:05:27.652958');CREATE TABLE refresh_tokens (
	id INTEGER NOT NULL, 
	jti VARCHAR(64) NOT NULL, 
	user_id INTEGER NOT NULL, 
	expires_at DATETIME NOT NULL, 
	revoked_at DATETIME, 
	created_at DATETIME NOT NULL, 
