	PRIMARY KEY (id)
);INSERT INTO "schema_version" VALUES(1,2,'courses, testimonials, phone, address, working hours');CREATE TABLE site_settings (
	"key" VARCHAR(64) NOT NULL, 
	value JSON, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY ("key")
);INSERT INTO "site_settings" VALUES('site_name','"Smart Start"','2026-11-07 10:05:37.162868');INSERT INTO "site_settings" VALUES('phone','"+998 98 560 07 20"','2026-11-11 03:06:39');INSERT INTO "site_settings" VALUES('telegram','"https://t.me/stmartstartt_bot"','2026-11-07 10:05:37.162870');INSERT INTO "site_settings" VALUES('instagram','""','2026-11-07 10:05:37.162871');INSERT INTO "site_settings" VALUES('address','"120100, Sirdaryo viloyati, Guliston, Al-Xorazmiy ko\u2018chasi, 36"','2026-11-11 03:06:39');INSERT INTO "site_settings" VALUES('work_hours_weekday','"Du\u2013Ju: 08:30\u201317:30"','2026-11-11 03:06:39');INSERT INTO "site_settings" VALUES('work_hours_saturday','"Sha: 08:30\u201312:00"','2026-11-11 03:06:39');INSERT INTO "site_settings" VALUES('working_hours','"Du\u2013Ju: 08:30\u201317:30, Sha: 08:30\u201312:00"','2026-11-11 03:06:39');CREATE TABLE teachers (
