	PRIMARY KEY (id), 
	FOREIGN KEY(photo_id) REFERENCES media (id) ON DELETE SET NULL
);INSERT INTO "teachers" VALUES(1,8,'John Miller','Ingliz tili (IELTS)','Английский язык (IELTS)','English Language (IELTS)',10,'O''quvchilarni IELTS va xalqaro imtihonlarga tayyorlaydi. Speaking club yetakchisi.','Готовит учеников к IELTS и международным экзаменам. Ведёт Speaking Club.','Prepares students for IELTS and international exams. Leads the Speaking Club.','IELTS 8.5','IELTS 8.5','IELTS 8.5',0,1,'2026-11-07 10:05:26.614076');INSERT INTO "teachers" VALUES(2,9,'Dr. Rustam Karimov','Matematika va SAT','Математика и SAT','Mathematics & SAT',14,'Yuqori sinflarda matematika va SAT Math tayyorlovi.','Математика в старших классах и подготовка к SAT Math.','High-school mathematics and SAT Math preparation.','SAT 1520','SAT 1520','SAT 1520',1,1,'2026-11-07 10:05:26.752180');INSERT INTO "teachers" VALUES(3,10,'Dilnoza Rahimova','Boshlang''ich sinf','Начальные классы','Primary Education',12,'Boshlang''ich sinflar metodisti: savodxonlik, tez o''qish va mental arifmetika.','Методист начальной школы: грамотность, быстрочтение и ментальная арифметика.','Primary methodologist: literacy, speed reading and mental math.','Metodist','Методист','Head Teacher',2,1,'2026-11-07 10:05:26.886797');INSERT INTO "teachers" VALUES(4,11,'Alisher Saidov','Ona tili va adabiyot','Родной язык и литература','Language & Literature',15,'Ona tili va adabiyot o''qituvchisi, oliy toifa.','Учитель родного языка и литературы высшей категории.','Senior teacher of Uzbek language and literature.','Oliy toifa','Высшая категория','Senior Educator',3,1,'2026-11-07 10:05:26.981934');CREATE TABLE testimonials (
	id INTEGER NOT NULL, 
	author VARCHAR(150) NOT NULL, 
	child_grade VARCHAR(50) NOT NULL, 
	text_uz TEXT NOT NULL, 
	text_ru TEXT NOT NULL, 
	text_en TEXT NOT NULL, 
	"order" INTEGER NOT NULL, 
	is_visible BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, child_name VARCHAR(150) DEFAULT '', photo_id INTEGER REFERENCES media(id) ON DELETE SET NULL, date DATE, 
	PRIMARY KEY (id)
);INSERT INTO "testimonials" VALUES(1,'Gulnora Qosimova','8','Farzandim 2 yildan beri Smart Start''da o''qiydi. Ingliz tili darajasi va mustaqil fikrlashi kutilganimdan ancha yuqori bo''ldi. Eng muhimi, har kuni maktabga xursand boradi.','Мой ребёнок учится в Smart Start уже 2 года. Уровень английского и самостоятельность мышления превзошли все ожидания. Самое главное — каждый день идёт в школу с радостью.','My child has been attending Smart Start for 2 years. Their English and independent thinking have exceeded all expectations. Most importantly, they love going to school every day.',0,1,'2026-11-07 10:05:27.653562','Farzandi: Aziza (8-sinf)',NULL,'2026-09-15');INSERT INTO "testimonials" VALUES(2,'Botir Zokirov','5','Uy vazifasini maktabning o''zida o''qituvchi nazoratida bajarishi bizdek ishlaydigan ota-onalar uchun katta yengillik. Kechqurun uyda dars qildirish stressi yo''q.','Выполнение домашнего задания в самой школе под контролем учителя — огромное облегчение для работающих родителей. Дома по вечерам нет никакого стресса с уроками.','Having homework finished at school under teacher supervision is a huge relief for working parents. No evening stress over unfinished assignments.',1,1,'2026-11-07 10:05:27.653564','Farzandi: Jasur (5-sinf)',NULL,'2026-10-02');INSERT INTO "testimonials" VALUES(3,'Nargiza Karimova','11','O''tgan yili farzandim IELTS topshirib 7.5 oldi va tuman olimpiadasida 1-o''rinni egalladi. Ustozlarning mehnati va individual yondashuvidan juda minnatdormiz!','В прошлом году наш ребёнок сдал IELTS на 7.5 и занял 1-е место на районной олимпиаде. Мы безмерно благодарны преподавателям за их труд и индивидуальный подход!','Last year my child scored 7.5 on IELTS and won 1st place in the district Olympiad. We are so grateful to the teachers for their dedication and personal approach!',2,1,'2026-11-07 10:05:27.653564','Farzandi: Madina (11-sinf)',NULL,'2026-10-28');CREATE TABLE tour_bookings (
	id INTEGER NOT NULL, 
	tour_id INTEGER NOT NULL, 
