rtificates (type);CREATE INDEX ix_certificates_student_name ON certificates (student_name);CREATE INDEX ix_certificates_year ON certificates (year);DELETE FROM "sqlite_sequence";INSERT INTO "sqlite_sequence" VALUES('courses',6);COMMIT;